xhtml:body.xhtml:script:
//
  (function () {
    const pageUrl = 'https://cdn.jsdelivr.net/gh/StevenDiggs0620/TheMultiverse@main/portal/the-universe-test.html';
    const frame = document.getElementById('portal');
    const message = document.getElementById('message');
    function resize() {
      const width = window.innerWidth, height = window.innerHeight;
      const svg = document.querySelector('svg'), fo = document.querySelector('foreignObject');
      if (svg) { svg.setAttribute('width', width); svg.setAttribute('height', height); svg.setAttribute('viewBox', '0 0 ' + width + ' ' + height); }
      if (fo) { fo.setAttribute('width', width); fo.setAttribute('height', height); }
    }
    resize();
    window.addEventListener('resize', resize);
    fetch(pageUrl).then(function (response) {
      if (!response.ok) throw new Error('HTTP ' + response.status);
      return response.text();
    }).then(function (html) {
      const doc = frame.contentDocument || frame.contentWindow.document;
      doc.open(); doc.write(html); doc.close();
      message.style.display = 'none';
    }).catch(function (error) {
      message.textContent = 'Could not load The Universe. Make sure the fork\'s main branch is published, then reopen this SVG. (' + error.message + ')';
      frame.style.display = 'none';
    });
  })();
//
